        [DllImport(Lib, EntryPoint = "TJARE_ARBody_GetSkeletonPointIsValid", CallingConvention = CallingConvention.Cdecl)]
        public static extern AREngine_ARStatus ARBody_GetSkeletonPointIsValid(IntPtr session, IntPtr body, out IntPtr outSkeletonPointIsValid);

        /// <summary>Obtains the connection data between skeleton points of a human body object. A connection is represented by the types of two skeleton points. For example, if the return value is [ARENGINE_ARBODY_SKELETON_R_WRIST, ARENGINE_ARBODY_SKELETON_R_ELBOW, ...], it indicates that the right wrist is connected to the right elbow to form a skeleton.</summary>
        /// <remarks>since 6.1.0(23)</remarks>
        [DllImport(Lib, EntryPoint = "TJARE_ARBody_GetSkeletonConnection", CallingConvention = CallingConvention.Cdecl)]
        public static extern AREngine_ARStatus ARBody_GetSkeletonConnection(IntPtr session, IntPtr body, out IntPtr outSkeletonConnection);

        /// <summary>Open the flash light of the device.</summary>
        /// <remarks>since 26.0.0</remarks>
        [DllImport(Lib, EntryPoint = "TJARE_ARSession_OpenFlash", CallingConvention = CallingConvention.Cdecl)]
        public static extern AREngine_ARStatus ARSession_OpenFlash(IntPtr session);

        /// <summary>Close the flash light of the device.</summary>
        /// <remarks>since 26.0.0</remarks>
        [DllImport(Lib, EntryPoint = "TJARE_ARSession_CloseFlash", CallingConvention = CallingConvention.Cdecl)]
        public static extern AREngine_ARStatus ARSession_CloseFlash(IntPtr session);

    }
